#!/bin/sh
if test "$#" -eq 1; then eval "set -- $1"; fi
livespec_record_file() { record_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-record-file-resolution.py"; if test ! -f "$record_program"; then echo "LIVESPEC_RECORD_FILE_PROGRAM_ABSENT: the Dispatcher-materialized generated-record-file resolution is not at $record_program, so whether a conflicted or committed generated record file matches its generator cannot be established" >&2; return 1; fi; python3 "$record_program" --state-dir "$state" "$@"; }; livespec_record_file_brief() { regen_brief=; if livespec_record_file --brief "$@"; then regen_brief=$(cat "$state/livespec-record-file-regenerate" 2>/dev/null || true); fi; }; livespec_push() {
  helper=$(printenv LIVESPEC_SANDBOX_GH_REFRESH_ROOT || true)
  if test -z "$helper"; then helper=/workspace/.livespec-gh-refresh; fi
  helper="$helper/bin/push_origin"
  if test -x "$helper"; then
    "$helper" "$@"
  else
    if test -n "$(printenv GITHUB_APP_ID)"; then
      case "$(git remote get-url --push origin)" in
        http://*|https://*)
          echo "LIVESPEC_PUSH_AUTH_ABSENT: push-time credential helper is missing" >&2
          return 1
          ;;
      esac
    fi
    "$@"
  fi
}
livespec_restore() { restore_head="$1"; if test -d "$(git rev-parse --git-path rebase-merge)" || test -d "$(git rev-parse --git-path rebase-apply)"; then git rebase --abort >/dev/null 2>&1 || true; fi; if test -f "$(git rev-parse --git-path MERGE_HEAD)"; then git merge --abort >/dev/null 2>&1 || true; fi; git reset --keep "$restore_head" >/dev/null 2>&1; }; livespec_refresh_repair() { repair_stage="$1"; repair_target="$2"; repair_label="$3"; repair_detail="$4"; repair_commit="$5"; repair_extra="${6:-}"; if test "$repair_count" -ge 2; then printf '%s\n' "refresh-repair-exhausted: $repair_stage would need a third refresh repair after $repair_count rounds, so this run is not converging on the moved default branch; recovery artifact pointer: this stage pre-refresh head is $pre_refresh" > "$reason_path"; echo "LIVESPEC_REFRESH_REPAIR_EXHAUSTED: refresh-repair-exhausted after $repair_count rounds; $repair_stage restored $pre_refresh and is failing closed to needs_human with that head as the recovery artifact pointer" >&2; return 0; fi; { printf 'LIVESPEC_REFRESH_REPAIR_BRIEF\n'; printf 'stage: %s\n' "$repair_stage"; printf 'pre-refresh-head: %s\n' "$pre_refresh"; printf 'refresh-target: %s\n' "$repair_target"; printf 'run-commit: %s\n' "$repair_commit"; printf '%s: %s\n' "$repair_label" "$repair_detail"; if test -n "$repair_extra"; then printf '%s\n' "$repair_extra"; fi; } > "$state/livespec-refresh-repair-brief"; printf '%s\n' "$((repair_count + 1))" > "$state/livespec-refresh-repair-count"; echo "LIVESPEC_REFRESH_REPAIR: $repair_stage restored $pre_refresh and recorded a refresh-repair brief, so this failure enters the fix node rather than needs_human" >&2; cat "$state/livespec-refresh-repair-brief" >&2; return 0; }; livespec_started_empty() { for started_empty in $(git rev-list --no-merges "$1..$2"); do if test -z "$(git diff-tree --no-commit-id --name-only -r "$started_empty")"; then printf '%s ' "$started_empty"; fi; done; }; livespec_record_file_merge() { merge_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-record-file-merge.py"; if test ! -f "$merge_program"; then echo "LIVESPEC_RECORD_FILE_MERGE_PROGRAM_ABSENT: the Dispatcher-materialized record-file merger is unavailable, so this conflict takes refresh repair" >&2; return 1; fi; merge_mode=$1; shift; python3 "$merge_program" --mode "$merge_mode" "$@"; }; livespec_rebase_active() { test -d "$(git rev-parse --git-path rebase-merge)" || test -d "$(git rev-parse --git-path rebase-apply)"; }; livespec_resolving_rebase() { resolving_target=$1; shift; git rebase "$@" "$resolving_target"; rebase_status=$?; if test "$rebase_status" -eq 0; then return 0; fi; merge_rounds=0; while test "$merge_rounds" -lt 16; do merge_rounds=$((merge_rounds + 1)); if ! livespec_rebase_active; then return "$rebase_status"; fi; merge_conflicted=$(git diff --name-only --diff-filter=U); if test -z "$merge_conflicted"; then return "$rebase_status"; fi; if ! livespec_record_file_merge rebase $merge_conflicted; then return 1; fi; record_merged=true; GIT_EDITOR=true git rebase --continue; rebase_status=$?; if test "$rebase_status" -eq 0; then return 0; fi; done; return 1; }; livespec_resolving_merge() { resolving_target=$1; if git merge --no-edit "$resolving_target"; then return 0; fi; merge_conflicted=$(git diff --name-only --diff-filter=U); if test -z "$merge_conflicted"; then return 1; fi; if ! livespec_record_file_merge merge $merge_conflicted; then return 1; fi; record_merged=true; GIT_EDITOR=true git commit --no-edit; }; livespec_refresh_onto_default() { refresh_target=$(git rev-parse "origin/$default_branch") || return $?; if test "$preserve_remote_ancestry" = true; then if test "$empties_dropped" != true; then empties_dropped=true; if test -n "$(livespec_started_empty "$remote_tip" HEAD)"; then livespec_resolving_rebase "$remote_tip" --no-keep-empty --force-rebase || return $?; fi; fi; livespec_resolving_merge "$refresh_target"; return $?; fi; refresh_base=$(git merge-base HEAD "$refresh_target"); refresh_status=$?; if test "$refresh_status" -ne 0; then return "$refresh_status"; fi; if test -n "$(livespec_started_empty "$refresh_base" HEAD)"; then livespec_resolving_rebase "$refresh_target" --no-keep-empty --force-rebase; return $?; fi; livespec_resolving_rebase "$refresh_target"; }; livespec_landed_check() { merged_lines=$(gh pr list --head "$branch" --base "$default_branch" --state merged --limit 100 --json number,mergeCommit,headRefOid --jq 'sort_by(.number)|reverse|.[]|[.number,.mergeCommit.oid,.headRefOid]|@tsv'); merged_status=$?; merged=$(printf '%s' "$merged_lines" | awk -F '	' -v dispatched="${LIVESPEC_DISPATCH_PULL_REQUESTS:-}" 'BEGIN { count = split(dispatched, parts, " "); for (index_ = 1; index_ <= count; index_++) named[parts[index_]] = 1 } ($1 in named) { print; exit }'); IFS=$(printf '	'); set -- $merged; unset IFS; merged_number=${1:-}; merged_commit=${2:-}; merged_head=${3:-}; if test "$merged_status" -eq 0 && test -n "$merged_number" && test "$(printf '%s' "$merged_commit" | tr -d 0123456789abcdef)" = "" && test "$(printf '%s' "$merged_commit" | wc -c)" -eq 40 && test -n "$merged_head"; then default_tip=$(git rev-parse "origin/$default_branch"); proof_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-publication-head.py"; proof_status=1; if test -f "$proof_program"; then proof_head=$(python3 "$proof_program" --pull-request "$merged_number" --latest-anchor-or-none); proof_status=$?; fi; if test "$proof_status" -eq 0 && git merge-base --is-ancestor "$merged_commit" "$default_tip" && git diff --quiet "$default_tip" HEAD; then heads_equal=false; if test "$proof_head" = "$merged_head"; then heads_equal=true; fi; { printf 'pull_request=%s\n' "$merged_number"; printf 'merge_commit=%s\n' "$merged_commit"; printf 'merged_head=%s\n' "$merged_head"; printf 'proof_head=%s\n' "$proof_head"; printf 'heads_equal=%s\n' "$heads_equal"; } > "$state/livespec-merged-reconcile"; echo "LIVESPEC_MERGED_RECONCILE: pull_request=$merged_number merge_commit=$merged_commit merged_head=$merged_head proof_head=$proof_head heads_equal=$heads_equal" >&2; exit 0; fi; fi; }; livespec_declared_gate() { livespec_suite_words=''
for livespec_suite_word in "$@"; do
  livespec_suite_quoted=$(printf '%s' "$livespec_suite_word" | sed "s/'/'\\''/g")
  livespec_suite_words="$livespec_suite_words '$livespec_suite_quoted'"
done
set --
eval "set -- $livespec_suite_words"; if test "$#" -eq 1; then eval "set -- $1"; fi; "$@"; }; livespec_bounded_push() { out_file=$1; shift; push_over_limit=false; figures="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-hook-limits.env"; observer="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-hook-limit.py"; budget=''; limit=''; if test -r "$figures"; then
# shellcheck source=/dev/null
. "$figures"; budget="${LIVESPEC_PUBLISH_DRAFT_PUSH_BUDGET_SECONDS:-}"; limit="${LIVESPEC_PUBLISH_DRAFT_LIMIT_SECONDS:-}"; fi; case "$budget" in ''|*[!0-9]*) livespec_push "$@" > "$out_file" 2>&1; return $? ;; esac; livespec_push "$@" > "$out_file" 2>&1 & push_pid=$!; waited=0; while :; do if ! kill -0 "$push_pid" 2>/dev/null; then wait "$push_pid"; return $?; fi; if test "$waited" -ge "$budget"; then break; fi; sleep 1; waited=$(( waited + 1 )); done; if test -r "$observer"; then python3 "$observer" --push-pid "$push_pid" --node publish_draft --operation push --hook-name pre-push --limit-seconds "$limit" || true; fi; kill -TERM "$push_pid" 2>/dev/null || true; wait "$push_pid" 2>/dev/null || true; push_over_limit=true; echo "LIVESPEC_PUBLISH_DRAFT_PUSH_OVER_LIMIT: the publish push was ended at its ${budget}s observation bound inside the ${limit}s publish_draft limit, so no pull request can carry the Proof of Done record; failing closed before proof capture with this run's work preserved by reference" >&2; return 1; }; livespec_publish_push() { if test -n "$republish_lease"; then livespec_bounded_push "$1" "$push_program" "$branch" "$republish_lease"; else livespec_bounded_push "$1" git push -u origin "HEAD:refs/heads/$branch"; fi; }; branch="${LIVESPEC_PUBLISH_BRANCH:-}"; if test -z "$branch"; then echo 'LIVESPEC_PUBLISH_DRAFT_NO_BRANCH: no LIVESPEC_PUBLISH_BRANCH in this script environment, so the publish branch cannot be named; failing closed before proof capture' >&2; exit 1; fi; reason_path=$(git rev-parse --git-path livespec-needs-human-reason); rm -f "$reason_path"; state=$(git rev-parse --git-path livespec-publication); regen_brief=; record_merged=false; mkdir -p "$state"; repair_pending=false; if test -s "$state/livespec-refresh-repair-brief"; then repair_pending=true; fi; rm -f "$state/livespec-refresh-repair-brief"; recorded_head=$(cat "$state/livespec-publish-head" 2>/dev/null || true); if test -z "$recorded_head"; then recorded_head="${LIVESPEC_RESUME_PUBLISHED_HEAD:-}"; fi; repair_count=$(cat "$state/livespec-refresh-repair-count" 2>/dev/null || echo 0); if ! test "$repair_count" -ge 0 2>/dev/null; then echo "LIVESPEC_REFRESH_REPAIR_COUNT_UNREADABLE: the recorded refresh-repair count $repair_count is not a number, so the two-round repair budget cannot be enforced; failing closed rather than repairing against a counter nothing can compare" >&2; exit 1; fi; pre_refresh=$(git rev-parse HEAD); default_branch="${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}"; git fetch origin "$default_branch" --quiet; status=$?; if test "$status" -ne 0; then echo "LIVESPEC_PUBLISH_DRAFT_REFRESH_FAILED: origin/$default_branch could not be fetched, so the publish branch base cannot be refreshed; failing closed before proof capture" >&2; exit "$status"; fi; base_before=$(git merge-base HEAD "origin/$default_branch"); status=$?; if test "$status" -ne 0; then echo "LIVESPEC_PUBLISH_DRAFT_REFRESH_FAILED: this run's base against origin/$default_branch could not be resolved; failing closed before proof capture" >&2; exit "$status"; fi; workflow_files=$(git diff --name-only "$base_before"..HEAD -- .github/workflows | tr '\n' ' '); if test -n "$workflow_files"; then reason="publish_draft refuses run-owned workflow file(s) $workflow_files because the GitHub App lacks workflows permission"; printf '%s\n' "$reason" > "$reason_path"; echo "LIVESPEC_PUBLISH_DRAFT_WORKFLOW_PERMISSION: $reason" >&2; exit 1; fi; remote_line=$(git ls-remote --heads origin "refs/heads/$branch"); status=$?; if test "$status" -ne 0; then echo "LIVESPEC_PUBLISH_DRAFT_REFRESH_FAILED: origin could not be queried for the existing publish branch $branch; failing closed before proof capture" >&2; exit "$status"; fi; remote_tip=${remote_line%%[[:space:]]*}; preserve_remote_ancestry=false; republish_lease=; push_program=; empties_dropped=false; if test -n "$remote_tip"; then git fetch origin "refs/heads/$branch" --quiet; status=$?; if test "$status" -ne 0; then echo "LIVESPEC_PUBLISH_DRAF