y refuse to rebase-merge" >&2; exit "$status"; fi; published_empties=$(livespec_started_empty "$published_base" "$remote_tip"); fi; if test -n "$published_empties"; then push_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-push-exact-head"; if test ! -x "$push_program"; then echo "LIVESPEC_PUBLISH_DRAFT_PUSH_PROGRAM_ABSENT: the Dispatcher-materialized exact-head push helper is not at $push_program, so the already-published tip $remote_tip cannot be rewritten under the required expected-object lease and its checkpoint commits that started empty would stay on the branch; failing closed rather than forcing bare or publishing a branch the forge may refuse to rebase-merge" >&2; exit 1; fi; republish_lease="$remote_tip"; preserve_remote_ancestry=false; echo "LIVESPEC_PUBLISH_DRAFT_PUBLISHED_EMPTY_COMMITS: origin/$branch is at $remote_tip, an ancestor of this run HEAD, and that tip itself carries checkpoint commits that started empty ($published_empties); the already-published ancestry cannot be preserved without republishing them, so this refresh rebases onto origin/$default_branch to drop them and republishes under an explicit lease against $remote_tip" >&2; fi; refresh_target=$(git rev-parse "origin/$default_branch"); livespec_refresh_onto_default; status=$?; if test "$status" -ne 0; then conflicted=$(git diff --name-only --diff-filter=U | tr '\n' ' '); applying=$(git rev-parse --verify --quiet REBASE_HEAD || printf '%s' "$pre_refresh"); livespec_record_file_brief $conflicted; if test -n "$conflicted" && livespec_restore "$pre_refresh"; then livespec_refresh_repair publish_draft "$refresh_target" conflicted-paths "$conflicted" "$applying" "$regen_brief"; exit 1; fi; livespec_restore "$pre_refresh"; echo "LIVESPEC_PUBLISH_DRAFT_REFRESH_FAILED: this run could not be refreshed onto origin/$default_branch and no path conflicted, so the refresh was undone and this working branch is restored to its pre-refresh head $pre_refresh; failing closed