$pre_refresh"; then livespec_refresh_repair publish_draft "$refresh_target" failed-gate-targets "$gate_targets" "$pre_refresh" "$regen_brief"; exit 1; fi; fi; fi; workflow_refusal='refusing to allow a GitHub App to create or update workflow'; push_tmp=$(mktemp); livespec_publish_push "$push_tmp"; status=$?; push_out=$(cat "$push_tmp"); rm -f "$push_tmp"; printf '%s\n' "$push_out" >&2; if test "$status" -ne 0 && printf '%s\n' "$push_out" | grep -qF "$workflow_refusal"; then echo "LIVESPEC_PUBLISH_DRAFT_WORKFLOW_RACE: GitHub refused the publish branch for a workflow file this run did not change, because origin/$default_branch moved its workflow files while the push was in flight; refreshing once more and retrying" >&2; git fetch origin "$default_branch" --quiet; status=$?; if test "$status" -eq 0; then livespec_refresh_onto_default; status=$?; fi; if test "$status" -ne 0; then livespec_restore "$pre_refresh"; echo "LIVESPEC_PUBLISH_DRAFT_REFRESH_FAILED: this run could not be refreshed again onto origin/$default_branch after the workflows-permission refusal, so the refresh was undone and this working branch is restored to its pre-refresh head $pre_refresh; failing closed before proof capture with that head as the recovery artifact pointer" >&2; exit "$status"; fi; gate_status=0; if livespec_record_file --check-head; then gate_out=$(livespec_declared_gate "$@" 2>&1); gate_status=$?; else gate_status=1; gate_out=$(cat "$state/livespec-record-file-targets" 2>/dev/null | tr '\n' ' '); regen_brief=$(cat "$state/livespec-record-file-regenerate" 2>/dev/null || true); if test -z "$(printf '%s' "$gate_out" | tr -d ' ')"; then gate_out='generated-record-file-uncheckable: whether this head committed generated record files are their generators output could not be established'; fi; fi; printf '%s\n' "$gate_out" >&2; if test "$gate_status" -ne 0; then gate_targets=$(printf '%s\n' "$gate_out" | tail -c 2000 | tr '\n' ' '); echo "LIVESPEC_PUBLISH_DRAFT_GATE_REJECTED: the repository declared gate refused the refreshed head, so the push could not publish it; restoring the head janitor passed and routing to the fix node" >&2; if livespec_restore "$pre_refresh"; then livespec_refresh_repair publish_draft "$refresh_target" failed-gate-targets "$gate_targets" "$pre_refresh" "$regen_brief"; exit 1; fi; fi; push_tmp=$(mktemp); livespec_publish_push "$push_tmp"; status=$?; push_out=$(cat "$push_tmp"); rm -f "$push_tmp"; printf '%s\n' "$push_out" >&2; if test "$status" -ne 0 && printf '%s\n' "$push_out" | grep -qF "$workflow_refusal"; then reason="publish_draft push refused twice by GitHub for a workflow file this run did not change, because origin/$default_branch kept changing workflow files during publication and the GitHub App lacks workflows permission; re-dispatch once the default branch is quiet"; printf '%s\n' "$reason" > "$reason_path"; echo "LIVESPEC_PUBLISH_DRAFT_WORKFLOW_PERMISSION: $reason" >&2; exit 1; fi; fi; if test "$status" -ne 0; then if test "$push_over_limit" = true; then exit 1; fi; gate_status=0; if ! printf '%s\n' "$push_out" | grep -qE 'LIVESPEC_PUSH_AUTH_|[Aa]uthentication failed|could not read Username|could not read Password|Invalid username or password|terminal prompts disabled|Permission denied|403 Forbidden|401 Unauthorized'; then if livespec_record_file --check-head; then gate_out=$(livespec_declared_gate "$@" 2>&1); gate_status=$?; else gate_status=1; gate_out=$(cat "$state/livespec-record-file-targets" 2>/dev/null | tr '\n' ' '); regen_brief=$(cat "$state/livespec-record-file-regenerate" 2>/dev/null || true); if test -z "$(printf '%s' "$gate_out" | tr -d ' ')"; then gate_out='generated-record-file-uncheckable: whether this head committed generated record files are their generators output could not be established'; fi; fi; fi; if test "$gate_status" -ne 0; then gate_targets=$(printf '%s\n' "$gate_out" | tail -c 2000 | tr '\n' ' '); echo "LIVESPEC_PUBLISH_DRAFT_GATE_REJECTED: the repository declared gate refused the refreshed head, so the push could not publish it; restoring the head janitor passed and routing to the fix node" >&2; if livespec_restore "$pre_refresh"; then livespec_refresh_repair publish_draft "$refresh_target" failed-gate-targets "$gate_targets" "$pre_refresh" "$regen_brief"; exit 1; fi; fi; echo 'LIVESPEC_PUBLISH_DRAFT_PUSH_FAILED: origin could not be reached, or refused the publish branch as non-fast-forward because it still carries a previous run of this item; no pull request can carry the Proof of Done record, so failing closed before proof capture. Remedy: clear or reconcile the stale publish branch, then re-dispatch' >&2; exit "$status"; fi; pushed=$(git rev-parse HEAD); state=$(git rev-parse --git-path livespec-publication); mkdir -p "$state"; printf '%s\n' "$pushed" > "$state/livespec-publish-head"; existing=$(gh pr list --head "$branch" --state open --json number --jq '.[0].number'); status=$?; if test "$status" -ne 0; then echo 'LIVESPEC_PUBLISH_DRAFT_LOOKUP_FAILED: the forge could not be asked whether a pull request is already open for the publish branch; failing closed rather than risk opening a second one' >&2; exit "$status"; fi; if test -n "$existing"; then echo "LIVESPEC_PUBLISH_DRAFT_EXISTS: pull request #$existing is already open for $branch; pushed this run HEAD and opened nothing" >&2; echo "LIVESPEC_PUBLISH_DRAFT_PUBLISHED: publish_branch=$branch head=$pushed pull_request=#$existing" >&2; exit 0; fi; created=$(gh pr create --draft --base "${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}" --head "$branch" --title "$branch" --body "Draft opened by the publish_draft stage so the Proof of Done record can be captured on it. The pr stage sets the real title and body, marks this ready and arms auto-merge."); status=$?; printf '%s\n' "$created"; if test "$status" -ne 0; then if git fetch origin "$default_branch" --quiet; then livespec_landed_check; fi; echo 'LIVESPEC_PUBLISH_DRAFT_CREATE_FAILED: no pull request is open for the publish branch and gh pr create failed;